async function generateSAFTAO(companyId, startDate, endDate, taxAccountingBasis = "F") {
  const companyInfo = await db.empresa.findUnique({
    where: { id: companyId }
  });
  if (!companyInfo) {
    throw new Error("Company not found");
  }
  const header = {
    AuditFileVersion: "1.01_01",
    CompanyID: companyInfo.nif,
    TaxRegistrationNumber: companyInfo.nif,
    TaxAccountingBasis: taxAccountingBasis,
    CompanyName: companyInfo.nome,
    BusinessName: companyInfo.nome,
    CompanyAddress: {
      AddressDetail: companyInfo.endereco,
      City: companyInfo.cidade || "Luanda",
      PostalCode: "1234-567",
      Country: "AO"
    },
    FiscalYear: (/* @__PURE__ */ new Date()).getFullYear(),
    StartDate: formatDate(startDate),
    EndDate: formatDate(endDate),
    CurrencyCode: "AOA",
    DateCreated: formatDate(/* @__PURE__ */ new Date()),
    TaxEntity: "Global",
    ProductCompanyTaxID: "5002097788",
    SoftwareValidationNumber: "FE/183/AGT/2026",
    ProductID: "FACT FLEX/AMANTENTE SOFT COMERCIO E SERVICOS LDA",
    ProductVersion: "0.1"
  };
  const customers = await fetchCustomers(companyId);
  const products = await fetchProducts(companyId);
  const taxTables = await fetchTaxTables();
  const invoices = await fetchInvoices(companyId, startDate, endDate);
  const workingDocuments = await fetchWorkindDocuments(companyId, startDate, endDate);
  const payments = await fetchPayments(companyId, startDate, endDate);
  const suppliers = await fetchSupliers(companyId);
  const purchaseInvoices = await fetchPurchaseInvoices();
  const generalLedgerAccounts = await fetchGeneralLedgerAccounts();
  const saftData = {
    Header: header,
    MasterFiles: {
      GeneralLedgerAccounts: generalLedgerAccounts,
      Customer: customers,
      Supplier: suppliers,
      Product: products,
      TaxTable: {
        TaxTableEntry: taxTables
      }
    },
    SourceDocuments: {
      SalesInvoices: invoices,
      PurchaseInvoices: purchaseInvoices,
      WorkingDocuments: workingDocuments,
      Payments: payments
    }
  };
  return buildXML(saftData);
}
async function fetchTaxTables() {
  const taxas = await db.taxa.findMany();
  const taxTables = taxas.map((taxa) => ({
    TaxType: taxa.tipo,
    TaxCountryRegion: taxa.regiao,
    TaxCode: taxa.codigo,
    Description: taxa.descricao,
    TaxPercentage: taxa.valor.toNumber()
  }));
  return taxTables;
}
async function fetchCustomers(companyId) {
  const clientes = await db.cliente.findMany({
    where: {
      empresaId: companyId
    }
  });
  const customers = clientes.map((cliente) => ({
    CustomerID: cliente.id.slice(0, 29),
    // Limitar o ID do cliente a 30 caracteres
    AccountID: "Desconhecido",
    CustomerTaxID: cliente.nif,
    CompanyName: cliente.nome,
    BillingAddress: {
      AddressDetail: cliente.endereco,
      City: cliente.cidade || "Luanda",
      Country: cliente.pais || "AO"
    },
    SelfBillingIndicator: 0
  }));
  return customers;
}
