function formatDate(date) {
  return date.toISOString().split("T")[0];
}
function buildXML(data) {
  const root = create({
    AuditFile: {
      "@xmlns": "urn:OECD:StandardAuditFile-Tax:AO_1.01_01",
      "@xmlns:xsi": "http://www.w3.org/2001/XMLSchema-instance",
      "@xsi:schemaLocation": "urn:OECD:StandardAuditFile-Tax:AO_1.01_01 https://raw.githubusercontent.com/assoft-portugal/SAF-T-AO/master/XSD/SAFTAO1.01_01.xsd",
      ...data
    }
  });
  return root.end({ prettyPrint: true });
}
async function fetchInvoices(companyId, start, end) {
  const invoicesDate = await db.documentoFiscal.findMany({
    where: {
      empresaId: companyId,
      tipoDocumento: {
        in: ["FACTURA", "FACTURA_RECIBO"]
      },
      createdAt: {
        gte: start,
        lte: end
      }
    },
    include: {
      itens: true,
      empresa: true,
      cliente: true
    }
  });
  const totalDebit = invoicesDate.reduce((acc, invoice) => {
    const invoiceTotal = invoice.itens.reduce((itemAcc, item) => {
      const qty = new Decimal(item.quantidade);
      const price = new Decimal(item.precoUnitario);
      return itemAcc.add(qty.mul(price));
    }, new Decimal(0));
    return acc.add(invoiceTotal);
  }, new Decimal(0));
  const invoices = {
    NumberOfEntries: invoicesDate.length,
    TotalDebit: totalDebit.toNumber(),
    TotalCredit: totalDebit.toNumber(),
    Invoice: invoicesDate.map((i) => ({
      InvoiceNo: i.numero.replace("-", " "),
      DocumentStatus: {
        InvoiceStatus: i.status == "ANULADO" ? "A" : "N",
        InvoiceStatusDate: i.updatedAt.toISOString(),
        Reason: i.observacao || "Sem observação",
        SourceID: i.empresaId.slice(0, 29),
        SourceBilling: "P"
      },
      Hash: i.hashDocumento,
      HashControl: i.hashDocumento?.slice(0, 4),
      Period: i.createdAt.getMonth() + 1,
      InvoiceDate: formatDate(i.createdAt),
      InvoiceType: mapInvoiceType(i.tipoDocumento),
      SpecialRegimes: {
        SelfBillingIndicator: 0,
        CashVATSchemeIndicator: 0,
        ThirdPartiesBillingIndicator: 0
      },
      SourceID: i.empresaId.slice(0, 29),
      //EACCode: "",
      //TransactionID: "",
      SystemEntryDate: i.createdAt.toISOString(),
      CustomerID: i.clienteId?.slice(0, 29),
      ShipTo: {
        Address: {
          AddressDetail: i.cliente?.endereco,
          City: "Luanda",
          Country: "AO"
        }
      },
      ShipFrom: {
        Address: {
          AddressDetail: i.empresa.endereco,
          City: i.empresa.cidade || "Luanda",
          Country: "AO"
        }
      },
      MovementEndTime: i.updatedAt.toISOString(),
      MovementStartTime: i.createdAt.toISOString(),
      Line: i.itens.map((l, index) => ({
        LineNumber: index,
        ProductCode: l.codigo,
        ProductDescription: l.descricao,
        Quantity: l.quantidade,
        UnitOfMeasure: l.unidade,
        UnitPrice: new Decimal(l.precoUnitario).toNumber(),
        TaxBase: new Decimal(l.taxa).toNumber(),
        TaxPointDate: formatDate(l.createdAt),
        Description: l.descricao,
        ProductSerialNumber: {
          SerialNumber: "1234567890"
        },
        DebitAmount: new Decimal(l.quantidade).mul(new Decimal(l.precoUnitario)).toNumber(),
        //CreditAmount: 1052520.85,
        Tax: {
          TaxType: l.motivoIsencao ? "NS" : "IVA",
          TaxCountryRegion: "AO",
          TaxCode: l.motivoIsencao ? "NOR" : "ISE",
          TaxPercentage: new Decimal(l.taxa).toNumber()
        },
        TaxExemptionReason: l.taxa.toNumber() == 0 ? getTaxExemptionReason(l.motivoIsencao) : void 0,
        TaxExemptionCode: l.taxa.toNumber() == 0 ? l.motivoIsencao : void 0
        //SettlementAmount: 1052520.85,
        // CustomsInformation: {
        //     ARCNo: "1234567890",
        //     IECAmount: 1052520.85,
        // },
      })),
      DocumentTotals: {
        TaxPayable: i.itens.reduce((acc, item) => {
          const qty = new Decimal(item.quantidade);
          const price = new Decimal(item.precoUnitario);
          const taxRate = new Decimal(item.taxa);
          return acc.add(qty.mul(price).mul(taxRate.div(100)));
        }, new Decimal(0)).toFixed(2),
        NetTotal: i.itens.reduce((acc, item) => {
          const qty = new Decimal(item.quantidade);
          const price = new Decimal(item.precoUnitario);
          return acc.add(qty.mul(price));
        }, new Decimal(0)).toFixed(2),
        GrossTotal: i.itens.reduce((acc, item) => {
          const qty = new Decimal(item.quantidade);
          const price = new Decimal(item.precoUnitario);
          const taxRate = new Decimal(item.taxa);
          return acc.add(qty.mul(price).mul(new Decimal(1).add(taxRate.div(100))));
        }, new Decimal(0)).toFixed(2),
        Currency: {
          CurrencyCode: "AOA",
          CurrencyAmount: "10000.84",
          ExchangeRate: "254.47"
        }
      },
      WithholdingTax: {
        WithholdingTaxType: "IVA",
        WithholdingTaxDescription: "IVA",
        WithholdingTaxAmount: 100
      }
    }))
  };
  return invoices;
}
