function mapInvoiceType(tipo) {
  switch (tipo) {
    case "FACTURA":
      return "FT";
    case "FACTURA_RECIBO":
      return "FR";
    case "FACTURA_SIMPLIFICADA":
      return "FS";
    case "FACTURA_GLOBAL":
      return "FT";
    case "FACTURA_ADIANTAMENTO":
      return "FT";
    case "NOTA_CREDITO":
      return "NC";
    case "NOTA_DEBITO":
      return "ND";
    default:
      return "FT";
  }
}
const POST = async ({ request }) => {
  const { startDate, endDate } = await request.json();
  const empresaId = await getEmpresaId(request);
  try {
    const data = await generateSAFTAO(empresaId, new Date(startDate), new Date(endDate));
    const fileName = `SAFT-AO_${startDate.replaceAll("-", "")}_${endDate.replaceAll("-", "")}.xml`;
    await db.saftExportHistory.create({
      data: {
        fileName,
        period: `${startDate} a ${endDate}`,
        status: "success"
      }
    });
    return json({ xml: data });
  } catch (error) {
    console.error("Error generating SAFT AO:", error);
    return json({ error: "Failed to generate SAFT AO" }, { status: 500 });
  }
};
